// brightnessMonitor?.brightness ?? 50: 50 without a monitor; brightness is a number, never null (NaN stays NaN)
// ii: the fallback 50 is on a 0..1 scale (brightness and OsdValueIndicator.value are fractions)
auto* monitor = this->brightnessMonitor.get();
return monitor != nullptr ? monitor->brightness.get() : 50.0;

